// src/jobs/jobs.controller.ts
import { Controller, Post, Body, Get } from '@nestjs/common';
import { PrismaService } from 'src/shared/services/prisma.service';
import type { CreateJobWithScenarioDto } from './job.dto';

@Controller('jobs')
export class JobsController {
  constructor(private prisma: PrismaService) {}

  @Get()
  async getJobs() {
    return this.prisma.jobDescription.findMany({
      orderBy: { createdAt: 'desc' },
      include: {
        _count: {
          select: { applications: true }, // Đếm số lượng hồ sơ để hiện lên UI
        },
      },
    });
  }

  @Post()
  async createJobAndScenario(@Body() dto: CreateJobWithScenarioDto) {
    // Logic Transaction lưu xuống DB giữ nguyên
    const result = await this.prisma.$transaction(async (tx) => {
      // Trong file job.controller.ts của NestJS
      const job = await tx.jobDescription.create({
        data: {
          title: dto.title,
          content: dto.content,
          // Nếu rỗng thì ép về null để Prisma bỏ qua check Unique
          hrEmail: dto.hrEmail ? dto.hrEmail : null,
        },
      });

      const scenario = await tx.testScenario.create({
        data: {
          jobId: job.id,
          title: dto.scenarioTitle,
          difficulty: dto.difficulty,
          timeLimit: dto.timeLimit,
          context: dto.scenarioContext,
          initialCode: {},
        },
      });

      return { job, scenario };
    });

    return { message: 'Tạo chiến dịch và đề thi thành công!', data: result };
  }
}



import { z } from 'zod';

export enum difficultyEnum {
  INTERN = 'Intern',
  JUNIOR = 'Junior',
  MID_LEVEL = 'Mid-level',
  SENIOR = 'Senior',
}

export const createJobWithScenarioSchema = z.object({
  title: z.string().min(5, 'Tiêu đề chiến dịch phải có ít nhất 5 ký tự'),
  content: z.string().min(50, 'Nội dung JD cần ít nhất 50 ký tự'),
  hrEmail: z.string().email('Định dạng email không hợp lệ').optional(),

  // --- Thông tin đính kèm cho bài Test ---
  scenarioTitle: z.string().min(5, 'Tiêu đề bài thi quá ngắn'),
  difficulty: z.enum([
    difficultyEnum.INTERN,
    difficultyEnum.JUNIOR,
    difficultyEnum.MID_LEVEL,
    difficultyEnum.SENIOR,
  ]),
  timeLimit: z.number().int().min(10, 'Thời gian làm bài tối thiểu là 10 phút'),
  scenarioContext: z.string().min(10, 'Bối cảnh (Context) không được để trống'),
});

export type CreateJobWithScenarioDto = z.infer<
  typeof createJobWithScenarioSchema
>;



