import {
  Injectable,
  Logger,
  InternalServerErrorException,
} from '@nestjs/common';
import { PrismaService } from 'src/shared/services/prisma.service';
import { GoogleGenerativeAI } from '@google/generative-ai';
import envConfig from 'src/shared/config';

@Injectable()
export class JobService {
  private readonly logger = new Logger(JobService.name);
  private genAI: GoogleGenerativeAI;

  constructor(private prisma: PrismaService) {
    this.genAI = new GoogleGenerativeAI(envConfig.SECRET_API_KEY);
  }

  // Hàm chuyển đổi văn bản thành Vector
  async generateEmbedding(text: string): Promise {
    const model = this.genAI.getGenerativeModel({
      model: 'text-embedding-004',
    });
    const result = await model.embedContent(text);
    return result.embedding.values;
  }

  async createJob(title: string, content: string, hrEmail: string) {
    this.logger.log(`Đang tạo Job Description: ${title}`);

    // Tạo bản ghi Job trong PostgreSQL trước để lấy ID
    const newJob = await this.prisma.jobDescription.create({
      data: {
        title,
        content,
        hrEmail,
      },
    });

    try {
      // Gọi Gemini nhúng nội dung JD thành Vector
      this.logger.log('Đang tạo Vector Embedding cho nội dung JD...');
      const embeddingVector = await this.generateEmbedding(content);
      const vectorString = `[${embeddingVector.join(',')}]`; // Định dạng mảng chuẩn của pgvector

      // Dùng Raw SQL để ép kiểu cập nhật cột Unsupported("vector")
      await this.prisma.$executeRawUnsafe(`
        UPDATE "JobDescription" 
        SET "embedding" = '${vectorString}'::vector 
        WHERE id = '${newJob.id}'
      `);

      this.logger.log('Tạo Job và lưu Vector thành công!');

      // Nhờ có TransformInterceptor, bạn chỉ cần return object đơn giản thế này thôi
      return {
        id: newJob.id,
        title: newJob.title,
        message: 'Tạo bài tuyển dụng và nhúng AI thành công',
      };
    } catch (error) {
      this.logger.error('Lỗi khi gọi API nhúng Vector:', error);
      // Nếu lỗi AI, có thể job vẫn tạo thành công nhưng không có vector, bạn có thể xử lý rollback nếu cần
      throw new InternalServerErrorException(
        'Lỗi hệ thống khi phân tích Vector cho JD',
      );
    }
  }
}



