import { SetMetadata } from '@nestjs/common';
import {
  AuthTypeType,
  AuthType,
  ConditionGuard,
  ConditionGuardType,
} from '../constants/auth.contant';

export const AUTH_TYPE_KEY = 'authType';

export type AuthTypeDecoratorPayload = {
  authTypes: AuthTypeType[];
  options: { condition: ConditionGuardType };
};

export const Auth = (
  authTypes: AuthTypeType[],
  options?: { condition: ConditionGuardType },
) => {
  return SetMetadata(AUTH_TYPE_KEY, {
    authTypes,
    options: options ?? { condition: ConditionGuard.And },
  });
};

export const IsPublic = () => Auth([AuthType.None]);



import { SetMetadata } from '@nestjs/common';
import { RoleTypeType } from '../constants/auth.contant';

export const ROLES_KEY = 'roles';

export const Roles = (...roles: RoleTypeType[]) =>
  SetMetadata(ROLES_KEY, roles);



import {
  CanActivate,
  ExecutionContext,
  Injectable,
  UnauthorizedException,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { AuthType, ConditionGuard } from '../constants/auth.contant';
import { AccessTokenGuard } from './jwt.guard';
import {
  AUTH_TYPE_KEY,
  AuthTypeDecoratorPayload,
} from '../decorators/auth.decorator';

@Injectable()
export class AuthenticationGuard implements CanActivate {
  private readonly authTypeGuardMap: Record;

  constructor(
    private readonly reflector: Reflector,
    private readonly accessTokenGuard: AccessTokenGuard,
  ) {
    this.authTypeGuardMap = {
      [AuthType.Bearer]: this.accessTokenGuard,
      [AuthType.None]: { canActivate: () => true },
    };
  }

  async canActivate(context: ExecutionContext): Promise {
    const authTypeValue = this.reflector.getAllAndOverride<
      AuthTypeDecoratorPayload | undefined
    >(AUTH_TYPE_KEY, [context.getHandler(), context.getClass()]) ?? {
      authTypes: [AuthType.Bearer],
      options: { condition: ConditionGuard.And },
    };

    const guards = authTypeValue.authTypes.map(
      (authType) => this.authTypeGuardMap[authType],
    );

    if (authTypeValue.options.condition === ConditionGuard.Or) {
      let error = new UnauthorizedException();
      for (const instance of guards) {
        const canActivate = await Promise.resolve(
          instance.canActivate(context),
        ).catch((err) => {
          error = err;
          return false;
        });
        if (canActivate) {
          return true;
        }
      }
      throw error;
    } else {
      for (const instance of guards) {
        const canActivate = await instance.canActivate(context);
        if (!canActivate) {
          throw new UnauthorizedException();
        }
      }
      return true;
    }
  }
}



