import { ExecutionContext, Injectable, CanActivate } from '@nestjs/common';
import { REQUEST_USER_KEY } from '../constants/auth.contant';
import { JwtAuthService } from '../services/jwt.service';
@Injectable()
export class AccessTokenGuard implements CanActivate {
  constructor(private readonly JwtAuthService: JwtAuthService) {}
  async canActivate(context: ExecutionContext): Promise {
    const request = context.switchToHttp().getRequest();
    const authHeader = request.headers.authorization;
    const accessToken =
      typeof authHeader === 'string' ? authHeader.split(' ')[1] : undefined;
    if (!accessToken) {
      return false;
    }
    try {
      const decodedAccessToken =
        await this.JwtAuthService.verifyAccessToken(accessToken);
      request[REQUEST_USER_KEY] = decodedAccessToken;
      return true;
    } catch {
      return false;
    }
  }
}
// Dùng cho kiểm tra access token trong request, sử dụng bằng cách thêm decorator @UseGuard(AuthGuard)



import {
  Injectable,
  CanActivate,
  ExecutionContext,
  ForbiddenException,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { REQUEST_USER_KEY, RoleTypeType } from '../constants/auth.contant';
import { ROLES_KEY } from '../decorators/role.decorator';

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    // 1. Lấy danh sách Roles được yêu cầu từ Decorator (vd: ['HR', 'TECH_LEAD'])
    const requiredRoles = this.reflector.getAllAndOverride(
      ROLES_KEY,
      [context.getHandler(), context.getClass()],
    );

    // 2. Nếu API không gắn @Roles() -> Không yêu cầu quyền đặc biệt -> Cho qua
    if (!requiredRoles) {
      return true;
    }

    // 3. Lấy thông tin User từ Request
    // (Lưu ý: User này đã được AccessTokenGuard/AuthenticationGuard giải mã và nhét sẵn vào request từ bước trước)
    const request = context
      .switchToHttp()
      .getRequest<Record>();
    const user = request[REQUEST_USER_KEY] as
      | { role: RoleTypeType }
      | undefined;

    // 4. Đề phòng rủi ro: Nếu không có user -> Chặn
    if (!user) {
      throw new ForbiddenException('Chưa xác thực thông tin người dùng');
    }

    // 5. Kiểm tra xem role của user (vd: CANDIDATE) có nằm trong mảng requiredRoles không?
    const hasRole = requiredRoles.includes(user.role);

    if (!hasRole) {
      throw new ForbiddenException(
        'Bạn không có đủ thẩm quyền để truy cập tài nguyên này',
      );
    }

    return true;
  }
}



/* eslint-disable @typescript-eslint/no-unsafe-member-access */
import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
} from '@nestjs/common';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';
import { Response as ExpressResponse } from 'express';

export interface Response {
  statusCode: number;
  message: string;
  data?: T;
}

@Injectable()
export class TransformInterceptor implements NestInterceptor<
  T,
  Response
> {
  intercept(
    context: ExecutionContext,
    next: CallHandler,
  ): Observable<Response> {
    return next.handle().pipe(
      map((res: any): Response => {
        const ctx = context.switchToHttp();
        const response = ctx.getResponse();
        const statusCode = response.statusCode;

        // Trường hợp 1: Controller không trả về gì (VD: Delete thành công)
        if (res === undefined || res === null) {
          return { statusCode, message: 'Success' };
        }

        // Trường hợp 2: Controller chủ động trả về { message: '...', data: ... }
        if (
          typeof res === 'object' &&
          'message' in res &&
          typeof res.message === 'string'
        ) {
          const formattedResponse: Response = {
            statusCode,
            message: res.message,
          };

          // Chỉ gắn thêm 'data' nếu Controller thực sự có truyền 'data'
          if ('data' in res && res.data !== undefined) {
            formattedResponse.data = res.data;
          }
          return formattedResponse;
        }

        // Trường hợp 3: Controller trả về Data thuần túy (Mảng, Object User, String,...)
        return {
          statusCode,
          message: 'Success',
          data: res,
        };
      }),
    );
  }
}



