import { Injectable } from '@nestjs/common';
import { PassportStrategy } from '@nestjs/passport';
import { Strategy, Profile } from 'passport-github2';
import envConfig from '../../shared/config';

@Injectable()
export class GithubStrategy extends PassportStrategy(Strategy, 'github') {
  constructor() {
    super({
      clientID: envConfig.GITHUB_CLIENT_ID,
      clientSecret: envConfig.GITHUB_CLIENT_SECRET,
      callbackURL: envConfig.GITHUB_CLIENT_CALLBACK_URL,
      scope: ['user:email', 'read:user'],
    });
  }

  async validate(accessToken: string, refreshToken: string, profile: Profile) {
    const { id, username, displayName, photos, emails } = profile;

    // Dữ liệu từ github
    const userProfile = {
      githubId: id,
      githubUsername: username,
      name: displayName || username,
      avatarUrl: photos?.[0]?.value,
      email: emails?.[0]?.value,
      githubAccessToken: accessToken,
    };

    return userProfile;
  }
}



import { config } from 'dotenv';
import z from 'zod';
import fs from 'fs';
import path from 'path';

// 1. Load file .env
config({
  path: '.env',
});

// 2. Kiểm tra file tồn tại (Dùng đúng tên file .env)
if (!fs.existsSync(path.resolve('.env'))) {
  console.error(
    '❌ Khong tim thay file .env tại đường dẫn:',
    path.resolve('.env'),
  );
  process.exit(1);
}

// 3. Định nghĩa Schema
const configSchema = z.object({
  DATABASE_URL: z.string().min(1),
  GITHUB_CLIENT_ID: z.string().min(1),
  GITHUB_CLIENT_SECRET: z.string().min(1),
  GITHUB_CLIENT_URL: z.string().min(1),
  GITHUB_CLIENT_CALLBACK_URL: z.string().min(1),
  ACCESS_TOKEN_SECRET: z.string().min(1),
  ACCESS_TOKEN_EXPIRES_IN: z.string().min(1),
  REFRESH_TOKEN_SECRET: z.string().min(1),
  REFRESH_TOKEN_EXPIRES_IN: z.string().min(1),
  SECRET_API_KEY: z.string().min(1),
});

// 4. Parse và Validate
const configServer = configSchema.safeParse(process.env);

if (!configServer.success) {
  // Nếu thất bại: In lỗi chi tiết từ Zod
  console.error(
    '❌ Invalid environment variables:',
    configServer.error.flatten().fieldErrors,
  );
  process.exit(1);
}

// 5. Export data đã được validate và có kiểu dữ liệu (Type-safe)
const envConfig = configServer.data;

console.log('✅ Environment variables loaded successfully.');

export default envConfig;



